with base as (select id, session_id, event_type, page, duration_sec, round(duration_sec * 1.07, 2) as duration_sec_scaled, coalesce(page, 'N/A') as resolved_page from web_events where to_date(event_time) >= '2023-04-01'), with_dims as (select e.id, e.session_id, e.page, e.duration_sec, e.duration_sec_scaled, e.resolved_page, s.country from base e left join sessions s on e.session_id = s.id where s.browser != 'Chrome'), ranked as (select * from with_dims qualify row_number() over (partition by country order by duration_sec_scaled desc nulls last, id asc) = 1), ranked_web_events as (select id, page, duration_sec from (select *, rank() over (partition by session_id order by duration_sec desc nulls first) as rn from ranked) x where rn = 1) select id, page, duration_sec from ranked_web_events order by id asc limit 10
